File: Shortfall.sol
293     function updateNextBidderBlockLimit(uint256 _nextBidderBlockLimit) external {
294         _checkAccessAllowed("updateNextBidderBlockLimit(uint256)");
295         require(_nextBidderBlockLimit != 0, "_nextBidderBlockLimit must not be 0");
296         uint256 oldNextBidderBlockLimit = nextBidderBlockLimit;
